/* ================== PARAMETER ================== *//*SELECT FROM OJDT H */DECLARE @FromDate DATE;DECLARE @ToDate   DATE;SET @FromDate = /* H.RefDate */ N'[%0]';SET @ToDate   = /* H.RefDate */ N'[%1]';/* ================== BEAS COST DETAIL (CHUẨN BEAS) ================== */WITH BEAS_COST_DETAIL AS(    /* 1. BEAS JOURNAL HISTORIE */    SELECT	    j.TransId,        J.U_belnrid  AS BELNR_ID,        J.U_belposid AS BELPOS_ID,        O.AcctCode   AS Account,        J.Debit      AS Debit,        J.Credit     AS Credit    FROM BEAS_JOURNAL_HISTORIE J    LEFT JOIN OACT O ON J.Account = O.AcctCode    WHERE J.U_belnrid IS NOT NULL      AND J.U_belposid IS NOT NULL    UNION ALL    /* 2. JE thường (không GI/GR) */    SELECT	   J.TransId,        OJ.U_belnrid,        OJ.U_belposid,        O.AcctCode,        J.Debit,        J.Credit    FROM JDT1 J    INNER JOIN OJDT OJ ON OJ.TransId = J.TransId    LEFT JOIN OACT O ON J.Account = O.AcctCode    WHERE OJ.TransType NOT IN (59,60)      AND OJ.U_belnrid IS NOT NULL      AND OJ.U_belposid IS NOT NULL    UNION ALL    /* 3. Goods Issue – NVL */    SELECT DISTINCT	    J.TransId,        I1.U_belnrid,        I1.U_belposid,        O.AcctCode,        J.Debit,        J.Credit    FROM JDT1 J    INNER JOIN OJDT OJ ON OJ.TransId = J.TransId    INNER JOIN OIGE OG ON OJ.CreatedBy = OG.DocEntry    INNER JOIN IGE1 I1 ON OG.DocEntry = I1.DocEntry    LEFT JOIN OACT O ON J.Account = O.AcctCode    WHERE OJ.TransType = 60   --   AND I1.U_belnrid  = 8092   --   AND I1.U_belposid = 10	  --and  O.AcctCode = '1541'	 AND I1.U_belnrid  IS NOT NULL      AND I1.U_belposid IS NOT NULL    UNION ALL    /* 4. Goods Receipt – FG */    SELECT DISTINCT		J.TransId,        R1.U_belnrid,        R1.U_belposid,        O.AcctCode,        J.Debit,        J.Credit    FROM JDT1 J    INNER JOIN OJDT OJ ON OJ.TransId = J.TransId    INNER JOIN OIGN ORH ON OJ.CreatedBy = ORH.DocEntry    INNER JOIN IGN1 R1 ON ORH.DocEntry = R1.DocEntry    LEFT JOIN OACT O ON J.Account = O.AcctCode    WHERE OJ.TransType = 59      AND R1.U_belnrid IS NOT NULL      AND R1.U_belposid IS NOT NULL),/* ================== PRE-AGG COST (PIVOT) ================== */COST_PIVOT AS(    SELECT        BELNR_ID,        BELPOS_ID,        SUM(CASE WHEN Account = '6229'  THEN Debit - Credit ELSE 0 END) AS C_6229,        SUM(CASE WHEN Account = '62719' THEN Debit - Credit ELSE 0 END) AS C_62719,        SUM(CASE WHEN Account = '62725' THEN Debit - Credit ELSE 0 END) AS C_62725,        SUM(CASE WHEN Account = '1521'  THEN Debit - Credit ELSE 0 END) AS C_1521,        SUM(CASE WHEN Account = '1541'  THEN Debit - Credit ELSE 0 END) AS C_1541,        SUM(CASE WHEN Account = '1551'  THEN Debit - Credit ELSE 0 END) AS C_1551,        SUM(CASE WHEN Account = '1552'  THEN Debit - Credit ELSE 0 END) AS C_1552    FROM BEAS_COST_DETAIL    GROUP BY BELNR_ID, BELPOS_ID),/* ================== ACTUAL FINISHED QTY (FG) ================== */FG_QTY AS(    SELECT        U_belnrid  AS BELNR_ID,        U_belposid AS BELPOS_ID,        ItemCode,        SUM(CASE WHEN Src = 'ISSUE'   THEN Qty ELSE 0 END) AS QtyIssue,        SUM(CASE WHEN Src = 'RECEIPT' THEN Qty ELSE 0 END) AS QtyReceipt    FROM    (        SELECT U_belnrid, U_belposid, ItemCode, Quantity AS Qty, 'ISSUE' AS Src        FROM IGE1 WHERE ISNULL(U_belnrid,'') <> ''        UNION ALL        SELECT U_belnrid, U_belposid, ItemCode, Quantity, 'RECEIPT'        FROM IGN1 WHERE ISNULL(U_belnrid,'') <> ''    ) X    GROUP BY U_belnrid, U_belposid, ItemCode),/* ================== ACTUAL TOTAL FG VALUE ================== */FG_VALUE AS(    SELECT        U_belnrid  AS BELNR_ID,        U_belposid AS BELPOS_ID,        SUM(DocTotal) AS DocTotal    FROM    (        /* ===== FG RECEIPT ===== */        SELECT            X.U_belnrid,            X.U_belposid,            O.DocTotal        FROM        (            SELECT DISTINCT                DocEntry,                U_belnrid,                U_belposid            FROM IGN1           WHERE ISNULL(U_posid,0) = 0              AND U_belnrid IS NOT NULL        ) X        INNER JOIN OIGN O            ON X.DocEntry = O.DocEntry        UNION ALL        /* ===== FG ISSUE (REVERSAL) ===== */        SELECT            X.U_belnrid,            X.U_belposid,            -O.DocTotal        FROM        (            SELECT DISTINCT                DocEntry,                U_belnrid,                U_belposid            FROM IGE1            WHERE ISNULL(U_posid,0) = 0              AND U_belnrid IS NOT NULL        ) X        INNER JOIN OIGE O            ON X.DocEntry = O.DocEntry    ) T    GROUP BY        U_belnrid,        U_belposid)/* ================== MAIN REPORT ================== */SELECT    H.BELNR_ID        AS 'Order Number',    H.TYP             AS 'Type',    P.BELPOS_ID       AS 'Sub order number',    H.BELDAT          AS 'Order Date',    P.ItemCode        AS 'Finished Good',    P.MENGE_VERBRAUCH AS 'Plan Finished QTY',    CASE        WHEN ISNULL(Q.QtyIssue,0) = 0            THEN ISNULL(Q.QtyReceipt,0)        ELSE ISNULL(Q.QtyReceipt,0) - ISNULL(Q.QtyIssue,0)    END               AS 'Actual finished Qty',    G.BalInvntAc      AS 'AcctCode FG',    V.DocTotal        AS 'Actual Total FG',    P.ABGKZ           AS 'Closed W/O',    P.ABGKZ_DATE      AS 'Closing Date',    CP.C_6229  AS '6229',    CP.C_62719 AS '62719',    CP.C_62725 AS '62725',    CP.C_1521  AS '1521',    CP.C_1541  AS '1541',    CP.C_1551  AS '1551',    CP.C_1552  AS '1552'FROM BEAS_FTHAUPT HINNER JOIN BEAS_FTPOS P    ON H.BELNR_ID = P.BELNR_IDINNER JOIN OITM I    ON P.ItemCode = I.ItemCodeINNER JOIN OITB G    ON I.ItmsGrpCod = G.ItmsGrpCodLEFT JOIN FG_QTY Q    ON Q.BELNR_ID  = H.BELNR_ID   AND Q.BELPOS_ID = P.BELPOS_ID   AND Q.ItemCode  = P.ItemCodeLEFT JOIN FG_VALUE V    ON V.BELNR_ID  = H.BELNR_ID   AND V.BELPOS_ID = P.BELPOS_IDLEFT JOIN COST_PIVOT CP    ON CP.BELNR_ID  = H.BELNR_ID   AND CP.BELPOS_ID = P.BELPOS_IDWHERE    P.ABGKZ_DATE BETWEEN @FromDate AND @ToDate	--and H.BELNR_ID  = 8119ORDER BY    H.BELNR_ID,    P.BELPOS_ID